const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const paths={today:'M12 3v2 M12 19v2 M3 12h2 M19 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M16 12a4 4 0 11-8 0 4 4 0 018 0',library:'M4 4h6v16H4z M10 4h5v16h-5 M17 4l4 15-4 1-4-15',archive:'M3 4h18v5H3z M5 9v12h14V9 M9 13h6',trash:'M4 6h16 M9 3h6 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',inbox:'M4 4h16v16H4z M4 13h5l2 3h2l2-3h5',task:'M5 3h14v18H5z M8 8l2 2 4-4 M8 15h8',note:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',project:'M3 7h7l2-3h9v16H3z',area:'M3 11l9-8 9 8 M6 9v12h12V9 M10 21v-7h4v7',resource:'M4 4h6v16H4z M10 4h5v16h-5 M17 4l4 15-4 1-4-15',link:'M9 15l6-6 M8 12l-2 2a4 4 0 005 5l3-3 M16 12l2-2a4 4 0 00-5-5l-3 3',history:'M4 9a9 9 0 111 9 M4 3v6h6 M12 7v5l3 2',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16'};
const icon=k=>`<span class="icon ${k}-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${paths[k]||paths.note}"/></svg></span>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const n=Math.floor(Math.random()*16);return(c==='x'?n:(n&3)|8).toString(16)}); const key='nook-clarification-prototype-v1';
function seed(){return{captures:[{id:'c1',body:'Bedroom lighting: warm lamps, dimmer switch, ask electrician for a quote.',createdAt:new Date(2026,8,30,21).getTime()},{id:'c2',body:'Read this article on sleep and keep the useful ideas.',createdAt:Date.now()-22*60000},{id:'c3',body:'Ask the contractor about the lighting ideas in my bedroom note.',createdAt:Date.now()-2*60000}],homes:[{id:'a1',kind:'area',title:'Home'},{id:'a2',kind:'area',title:'Health'},{id:'p1',kind:'project',title:'Bedroom refresh',area:'a1'},{id:'p2',kind:'project',title:'Build Nook'},{id:'r1',kind:'resource',title:'Sleep research'},{id:'r2',kind:'resource',title:'Interior inspiration'}],items:[{id:'n1',kind:'note',title:'Lighting ideas',body:'Warm light in the evening. A dimmer beside the bed. Keep ceiling lighting soft.',home:'p1',links:[]},{id:'t1',kind:'task',title:'Measure the bedroom',home:'p1',schedule:localDate(),deadline:'',links:['n1'],completed:false},{id:'t2',kind:'task',title:'Choose bedroom lamps',home:'p1',schedule:localDate(new Date(Date.now()+2*86400000)),deadline:'',links:[],completed:false}],history:[],archived:[]};}
let state;try{state=JSON.parse(localStorage.getItem(key))||seed()}catch{state=seed()}
let draft=null,route='today',filter='';
const titleCase=k=>k[0].toUpperCase()+k.slice(1);
const noteTitle=body=>body.split(/[.:\n]/)[0].slice(0,90).trim()||'Untitled note';
function suggestedHome(body){const words=body.toLowerCase().match(/[a-z]{4,}/g)||[];return state.homes.find(h=>h.kind==='project'&&h.title.toLowerCase().split(/\s+/).some(w=>words.includes(w)))||null}
function persist(){localStorage.setItem(key,JSON.stringify(state))}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200)}
function timestamp(ms){const m=Math.floor(Math.max(0,Date.now()-ms)/60000);return m<1?'Just now':m<60?`${m} ${m===1?'minute':'minutes'} ago`:new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}).format(ms)}
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dateLabel(s){if(!s)return 'Not scheduled';return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(s+'T12:00:00'))}
function homeLabel(id){const h=state.homes.find(x=>x.id===id);return h?h.title+(h.area?' / '+(state.homes.find(x=>x.id===h.area)?.title||''):''):'No home yet'}
function go(path){location.hash=path;render()}
function heading(title,sub){return `<h1>${title}</h1><p>${sub}</p>`}
function nav(){const page=route.split('/')[0];$('#nav').innerHTML=[['today','Today'],['inbox','Inbox'],['project','Projects'],['library','Library']].map(([i,t])=>`<a href="#${i}" class="${page===i||(i==='inbox'&&page==='clarify')||(i==='library'&&['task','history','home','item'].includes(page))?'active':''}">${icon(i)}${t}</a>`).join('')}
function captureRow(c){return `<button class="list-item" data-clarify="${c.id}">${icon('inbox')}<span class="words"><strong>${esc(c.body)}</strong><small>${timestamp(c.createdAt)}</small></span><span aria-hidden="true">›</span></button>`}
function itemRow(i){return `<div class="row ${i.completed?'done':''}">${i.kind==='task'?`<button class="completion" data-complete="${i.id}" aria-label="${i.completed?'Mark incomplete':'Complete'} ${esc(i.title)}">${i.completed?'✓':''}</button>`:''}<button class="list-item" data-item="${i.id}">${icon(i.kind)}<span class="words"><strong>${esc(i.title)}</strong><small>${esc(homeLabel(i.home))}${i.schedule?' · '+dateLabel(i.schedule):''}</small></span><span>›</span></button></div>`}
function render(){route=location.hash.slice(1)||'today';nav();document.body.dataset.page=route.split('/')[0];const [page,id]=route.split('/');
 if(page==='clarify'){const c=state.captures.find(c=>c.id===id);if(!c){go('inbox');return}if(!draft||draft.source!==id)draft={source:id,original:c.body,body:c.body,kind:c.type==='task'?'task':'note',noteTitle:noteTitle(c.body),noteBody:c.body,taskTitle:c.type==='task'?c.body:'',home:'',links:[],schedule:'',deadline:'',details:false};renderClarify(c);return}
 draft=null;
 if(page==='today'){
 const today=localDate(),tasks=state.items.filter(i=>i.kind==='task'&&!i.completed),due=tasks.filter(i=>i.schedule&&i.schedule<=today),next=tasks.filter(i=>i.schedule>today||i.deadline>today).sort((a,b)=>(a.deadline||a.schedule).localeCompare(b.deadline||b.schedule));
 app.innerHTML=heading('Good morning.',due.length?`${due.length} ${due.length===1?'thing':'things'} worth doing.`:'A little room to focus.')+`<section class="panel today-card"><div class="row between"><span class="pill yellow">Today</span><button class="quiet" id="all-tasks">All tasks</button></div><div class="task-list">${(due.length?due:tasks.slice(0,3)).slice(0,3).map(itemRow).join('')||'<p>No tasks planned. Capture a thought when it comes to mind.</p>'}</div></section><section class="panel upcoming-card"><h3>Coming up</h3>${next.slice(0,3).map(i=>`<button class="upcoming-row" data-item="${i.id}"><span>${new Date((i.deadline||i.schedule)+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span><strong>${esc(i.title)}</strong></button>`).join('')||'<p>Your scheduled tasks and deadlines will appear here.</p>'}</section><section class="inbox-status"><span class="status-icon">${icon('inbox')}</span><div><strong>Inbox · ${state.captures.length}</strong><small>${state.captures.length?'A few thoughts are waiting.':'Nothing waiting to clarify.'}</small></div><button class="primary" id="process-inbox" ${state.captures.length?'':'disabled'}>Process</button></section><button class="quiet new-task" id="new-task">+ Add task</button>`;
 $('#all-tasks').onclick=()=>go('task');$('#process-inbox').onclick=()=>go('clarify/'+state.captures[0].id);$('#new-task').onclick=showNewTask;
 }
 else if(page==='inbox'){app.innerHTML=heading('Inbox',`${state.captures.length} ${state.captures.length===1?'thought':'thoughts'} to clarify.`)+`<button class="capture-field" id="inline-capture">${icon('inbox')}<span>Write anything…</span><b>+ Capture</b></button><input id="search-inbox" placeholder="Find a thought" aria-label="Find a thought" value="${esc(filter)}"><div class="list" id="capture-list">${state.captures.filter(c=>c.body.toLowerCase().includes(filter.toLowerCase())).map(captureRow).join('')||'<p class="empty">No thoughts here. Capture something whenever it comes to mind.</p>'}</div>`;$('#inline-capture').onclick=showCapture;$('#search-inbox').oninput=e=>{filter=e.target.value;$('#capture-list').innerHTML=state.captures.filter(c=>c.body.toLowerCase().includes(filter.toLowerCase())).map(captureRow).join('');bindRows()}}
 else if(page==='task'){app.innerHTML=heading('Tasks','A clear action, a place to belong.')+`<div class="list">${state.items.filter(i=>i.kind==='task').map(itemRow).join('')||'<p class="empty">Turn a thought into your first Task.</p>'}</div>`}
 else if(page==='project'||page==='library'){
 const groups=page==='project'?['project']:['area','resource'];app.innerHTML=heading(page==='project'?'Projects':'Library',page==='project'?'Work toward an outcome.':'Everything has somewhere to belong.')+groups.map(k=>`<section class="home-group"><h3>${titleCase(k)}s</h3><div class="list">${state.homes.filter(h=>h.kind===k).map(h=>`<button class="list-item" data-home="${h.id}">${icon(h.kind)}<span class="words"><strong>${esc(h.title)}</strong><small>${titleCase(h.kind)} · ${state.items.filter(i=>i.home===h.id).length} items</small></span><span>›</span></button>`).join('')}</div></section>`).join('');
 if(page==='library')app.innerHTML+=`<div class="utility-links"><a href="#task">${icon('task')}Tasks</a><a href="#history">${icon('history')}Processed history & archive</a><button class="quiet" id="widget">Capture widget concept</button></div>`;if($('#widget'))$('#widget').onclick=showWidget;
 }
 else if(page==='home'){const h=state.homes.find(h=>h.id===id);if(!h){go('project');return}const children=state.homes.filter(x=>x.area===id);app.innerHTML=`<button class="back" onclick="location.hash='project'">‹ Library</button>`+heading(esc(h.title),`${h.kind[0].toUpperCase()+h.kind.slice(1)}${h.area?' in '+esc(homeLabel(h.area)):''}`)+children.map(x=>`<button class="home" data-home="${x.id}">${icon(x.kind)}${esc(x.title)}<span>›</span></button>`).join('')+`<div class="list">${state.items.filter(i=>i.home===id||children.some(h=>h.id===i.home)).map(itemRow).join('')||'<p class="empty">Choose this home when clarifying a thought.</p>'}</div>`}
 else if(page==='history'){app.innerHTML=heading('Processed history','Original thoughts and where they went.')+state.history.map(h=>`<section class="section"><small>Captured ${timestamp(h.createdAt)}</small><div class="detail-body">${esc(h.original)}</div>${h.clarifiedBody!==h.original?`<p>Edited during clarification: ${esc(h.clarifiedBody)}</p>`:''}<small>Processed ${timestamp(h.processedAt)}</small>${h.results.map(id=>state.items.find(i=>i.id===id)).filter(Boolean).map(itemRow).join('')}</section>`).join('')+(state.history.length?'':'<p class="empty">Processed thoughts will appear here.</p>')+`<section class="section"><h2>Archived thoughts</h2>${state.archived.map(c=>`<div class="section"><p>${esc(c.body)}</p><button data-restore="${c.id}">Restore to Inbox</button></div>`).join('')||'<p>No archived thoughts.</p>'}</section>`}
 else if(page==='item'){renderItem(id);return}
 else{go('inbox');return}if(page==='home'){const related=state.items.filter(i=>i.home!==id&&i.links?.includes(id));if(related.length)app.innerHTML+='<section class="section"><h3>Related items</h3>'+related.map(itemRow).join('')+'</section>'}bindRows();}
function bindRows(){document.querySelectorAll('[data-clarify]').forEach(b=>b.onclick=()=>go('clarify/'+b.dataset.clarify));document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>go('item/'+b.dataset.item));document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>go('home/'+b.dataset.home));document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{const i=state.items.find(x=>x.id===b.dataset.complete);i.completed=!i.completed;persist();render()});document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{const c=state.archived.find(x=>x.id===b.dataset.restore);state.archived=state.archived.filter(x=>x.id!==c.id);state.captures.push(c);persist();render();toast('Restored to Inbox')})}
function renderClarify(c){
 const d=draft,suggestion=!d.home?suggestedHome(d.body):null;
 app.innerHTML=`<div class="row between"><button class="back" id="back">‹ Inbox</button><small>${state.captures.indexOf(c)+1} of ${state.captures.length}</small><button class="quiet more" id="more" aria-label="More actions for this thought">•••</button></div><h1>Clarify</h1><section class="panel thought-card"><div class="row between"><span class="pill orange">Thought</span><small>${timestamp(c.createdAt)}</small></div><label class="sr-only" for="body">Edit thought</label><textarea id="body" class="thought">${esc(d.body)}</textarea></section><section class="clarify-options"><h3>Keep it as…</h3><div class="type-choices">${[['task','Task'],['note','Note']].map(([k,t])=>`<button data-kind="${k}" class="${d.kind===k?'active '+k:''}" aria-pressed="${d.kind===k}">${icon(k)}${t}</button>`).join('')}<button id="split" class="${d.kind==='both'?'active':''}" aria-pressed="${d.kind==='both'}">${icon('link')}${d.kind==='both'?'Note + Task':'Split'}</button></div>${d.kind==='both'?`<div class="split-field"><label for="task-title">Action to take</label><input id="task-title" value="${esc(d.taskTitle)}" placeholder="e.g. Ask electrician for a quote"><small>Saved as a Task linked to the Note.</small></div>`:''}<button class="home" id="choose-home">${icon(state.homes.find(h=>h.id===d.home)?.kind||'project')}<span>${d.home?esc(homeLabel(d.home)):'Add to…'}<small>${d.home?titleCase(state.homes.find(h=>h.id===d.home).kind):'Project, Area, or Resource · optional'}</small></span><span>›</span></button>${suggestion?`<button class="suggestion" id="suggested-home">${icon(suggestion.kind)}Use ${esc(suggestion.title)}</button>`:''}${d.kind!=='note'?`<div class="schedule-compact"><div class="chips"><button data-day="0">Today</button><button data-day="1">Tomorrow</button><button id="schedule">${icon('calendar')}${d.schedule?dateLabel(d.schedule):'Schedule'}</button></div>${d.schedule?'<button class="quiet" id="clear-schedule">Clear date</button>':''}</div>`:''}<div class="secondary-controls"><button class="quiet" id="link-items">${icon('link')}${d.links.length?d.links.length+' linked':'Link item'}</button><button class="quiet" id="details">${d.details?'Fewer options':'More options'}</button></div>${d.links.length?`<div class="linked-chips">${d.links.map(id=>{const i=[...state.items,...state.homes].find(i=>i.id===id);return `<button data-unlink="${id}" aria-label="Remove link to ${esc(i.title)}">${icon(i.kind)}${esc(i.title)} ×</button>`}).join('')}</div>`:''}${d.details?`<div class="extra-options">${d.kind!=='task'?`<label for="note-title">Note title</label><input id="note-title" value="${esc(d.noteTitle)}">${d.kind==='both'?`<label for="note-body">Note content</label><textarea id="note-body">${esc(d.noteBody)}</textarea>`:''}`:''}${d.kind!=='note'?`<button class="home" id="deadline">${icon('calendar')}Deadline<span>${d.deadline?dateLabel(d.deadline):'Optional'}</span></button>`:''}<button class="quiet" id="preview">Preview before saving</button></div>`:''}</section><div class="clarify-save"><button class="primary full" id="save">Save ${d.kind==='both'?'Note + Task':titleCase(d.kind)} & next</button></div>`;
 $('#back').onclick=()=>{c.body=d.body;persist();go('inbox')};$('#body').oninput=e=>{const prev=d.body;d.body=e.target.value;if(d.noteBody===prev)d.noteBody=d.body;if(d.noteTitle===noteTitle(prev))d.noteTitle=noteTitle(d.body);if(d.kind==='task'&&(d.taskTitle===prev||!d.taskTitle))d.taskTitle=d.body};
 for(const [id,k] of [['note-title','noteTitle'],['note-body','noteBody'],['task-title','taskTitle']])if($('#'+id))$('#'+id).oninput=e=>d[k]=e.target.value;
 document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{d.kind=b.dataset.kind;if(d.kind==='task')d.taskTitle=d.body;renderClarify(c)});
 $('#split').onclick=()=>{d.kind=d.kind==='both'?'note':'both';if(d.kind==='both'&&(!d.taskTitle||d.taskTitle===d.body)){const action=d.body.match(/(?:^|[,;.])\s*((?:ask|call|email|buy|read|send|book|schedule|research)\b[^.;]*)/i);d.taskTitle=action?titleCase(action[1].trim()):''}renderClarify(c)};
 $('#choose-home').onclick=()=>homePicker(d.home,id=>{d.home=id;renderClarify(c)});if($('#suggested-home'))$('#suggested-home').onclick=()=>{d.home=suggestion.id;renderClarify(c)};
 $('#link-items').onclick=()=>linkPicker(d.links,ids=>{d.links=ids;renderClarify(c)});document.querySelectorAll('[data-unlink]').forEach(b=>b.onclick=()=>{d.links=d.links.filter(id=>id!==b.dataset.unlink);renderClarify(c)});
 if(d.kind!=='note'){document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{const date=new Date();date.setDate(date.getDate()+Number(b.dataset.day));d.schedule=localDate(date);renderClarify(c)});$('#schedule').onclick=()=>datePicker('Schedule',d.schedule,v=>{d.schedule=v;renderClarify(c)});if($('#deadline'))$('#deadline').onclick=()=>datePicker('Deadline',d.deadline,v=>{d.deadline=v;renderClarify(c)});if($('#clear-schedule'))$('#clear-schedule').onclick=()=>{d.schedule='';renderClarify(c)}}
 $('#details').onclick=()=>{d.details=!d.details;renderClarify(c)};$('#save').onclick=saveClarification;
 if($('#preview'))$('#preview').onclick=()=>{if(!validDraft())return;openModal('Ready to save',preview()+`<div class="actions"><button class="primary" id="confirm-save">Save & next</button></div>`);$('#confirm-save').onclick=()=>{modal.close();saveClarification()}};
 $('#more').onclick=()=>openModal('Thought actions',`<button class="picker-item" id="archive">${icon('archive')}<span>Archive<small>Set aside. Restore it from Library later.</small></span></button><button class="picker-item danger" id="delete">${icon('trash')}<span>Delete<small>Permanently remove this thought.</small></span></button>`,()=>{
 $('#archive').onclick=()=>{state.archived.push({...c,body:d.body});state.captures=state.captures.filter(x=>x.id!==c.id);persist();modal.close();goNext();toast('Thought archived')};$('#delete').onclick=()=>{modal.close();openModal('Delete this thought?',`<p>This permanently removes the thought from the prototype.</p><div class="actions"><button id="cancel-delete">Keep thought</button><button class="danger" id="confirm-delete">Delete thought</button></div>`,()=>{$('#cancel-delete').onclick=()=>modal.close();$('#confirm-delete').onclick=()=>{state.captures=state.captures.filter(x=>x.id!==c.id);persist();modal.close();goNext();toast('Thought deleted')}})}});
}
function validDraft(){if(!draft.body.trim()){toast('Add some text to your thought');return false}if(draft.kind!=='task'&&(!draft.noteTitle.trim()||!draft.noteBody.trim())){toast('Add a Note title and content');return false}if(draft.kind!=='note'&&!draft.taskTitle.trim()){toast('Write the action for your Task');$('#task-title').focus();return false}return true}
function preview(){const d=draft;return `${d.kind!=='task'?`<section class="preview"><div class="row">${icon('note')}<strong>${esc(d.noteTitle)}</strong></div><p>${esc(d.noteBody)}</p><small>${esc(homeLabel(d.home))}</small></section>`:''}${d.kind!=='note'?`<section class="preview task section"><div class="row">${icon('task')}<strong>${esc(d.taskTitle)}</strong></div><p>${esc(homeLabel(d.home))}</p><small>Schedule: ${dateLabel(d.schedule)}${d.deadline?' · Deadline: '+dateLabel(d.deadline):''}</small></section>`:''}${d.kind==='both'?'<p>The Note and Task will be connected.</p>':''}${d.links.length?`<p>Also linked to ${d.links.map(id=>esc([...state.items,...state.homes].find(i=>i.id===id)?.title)).join(', ')}.</p>`:''}`}
function goNext(){draft=null;go(state.captures.length?'clarify/'+state.captures[0].id:'inbox')}
function saveClarification(){if(!validDraft())return;const d=draft,c=state.captures.find(c=>c.id===d.source),results=[];if(d.kind!=='task')results.push({id:uid(),kind:'note',title:d.noteTitle.trim(),body:d.noteBody,home:d.home,links:[...d.links]});if(d.kind!=='note')results.push({id:uid(),kind:'task',title:d.taskTitle.trim(),home:d.home,links:[...d.links],schedule:d.schedule,deadline:d.deadline,completed:false});if(results.length===2){results[0].links.push(results[1].id);results[1].links.push(results[0].id)}state.items.push(...results);state.history.unshift({id:uid(),original:c.body,clarifiedBody:d.body,createdAt:c.createdAt,processedAt:Date.now(),results:results.map(i=>i.id)});state.captures=state.captures.filter(x=>x.id!==c.id);persist();goNext();toast(`Saved ${results.length===2?'Note and Task':results[0].kind==='task'?'Task':'Note'} to ${homeLabel(d.home)}`)}
function openModal(title,body,ready,dismiss){modal.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button id="close-modal" aria-label="Close dialog">×</button></div>${body}`;$('#close-modal').onclick=()=>{modal.close();dismiss?.()};modal.oncancel=e=>{e.preventDefault();modal.close();dismiss?.()};modal.showModal();if(ready)ready()}
function homePicker(current,choose,cancel){
 openModal('Add to a Project, Area, or Resource',`<input id="home-search" placeholder="Search homes" aria-label="Search Projects, Areas, Resources"><div id="home-options"></div><button class="quiet" id="new-home">+ Create new</button>`,undefined,cancel);
 function list(q=''){const groups=['project','area','resource'];$('#home-options').innerHTML=`<button class="picker-item" data-choice="">No home</button>`+groups.map(kind=>{const homes=state.homes.filter(h=>h.kind===kind&&h.title.toLowerCase().includes(q.toLowerCase()));return homes.length?`<section class="picker-group"><h3>${titleCase(kind)}s</h3>${homes.map(h=>`<button class="picker-item ${current===h.id?'active':''}" data-choice="${h.id}">${icon(kind)}<span>${esc(h.title)}<small>${titleCase(kind)}${h.area?' in '+esc(homeLabel(h.area)):''}</small></span>${current===h.id?'<span>✓</span>':''}</button>`).join('')}</section>`:''}).join('');document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{modal.close();choose(b.dataset.choice)})}list();$('#home-search').oninput=e=>list(e.target.value);
 $('#new-home').onclick=()=>{modal.close();let kind='project';openModal('Create a home',`<div class="chips">${['project','area','resource'].map(k=>`<button data-new-kind="${k}" class="${k===kind?'active':''}">${icon(k)}${titleCase(k)}</button>`).join('')}</div><label for="home-name">Name</label><input id="home-name"><div class="actions"><button class="primary full" id="create-home">Create and assign</button></div>`,undefined,cancel);document.querySelectorAll('[data-new-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.newKind;document.querySelectorAll('[data-new-kind]').forEach(x=>x.classList.toggle('active',x===b))});$('#create-home').onclick=()=>{const title=$('#home-name').value.trim();if(!title)return;const h={id:uid(),kind,title};state.homes.push(h);persist();modal.close();choose(h.id)}}
}
function linkPicker(selected,choose){let ids=[...selected];openModal('Connect related items',`<input id="link-search" placeholder="Search Notes, Tasks, or collections" aria-label="Search related items"><div id="link-options"></div><button class="primary" id="done-links">Save links</button>`);function list(q=''){const entries=[...state.items,...state.homes];$('#link-options').innerHTML=entries.filter(i=>i.title.toLowerCase().includes(q.toLowerCase())).map(i=>`<button class="picker-item" data-link="${i.id}" aria-pressed="${ids.includes(i.id)}">${icon(i.kind)}<span>${esc(i.title)}<small>${titleCase(i.kind)}</small></span><span style="margin-left:auto">${ids.includes(i.id)?'✓':'+'}</span></button>`).join('');document.querySelectorAll('[data-link]').forEach(b=>b.onclick=()=>{ids=ids.includes(b.dataset.link)?ids.filter(id=>id!==b.dataset.link):[...ids,b.dataset.link];list(q)})}list();$('#link-search').oninput=e=>list(e.target.value);$('#done-links').onclick=()=>{modal.close();choose(ids)}}
function datePicker(title,value,choose,cancel){let view=value?new Date(value+'T12:00:00'):new Date(),selected=value;view.setDate(1);openModal(title,`<p>${title==='Schedule'?'When do you plan to work on it?':'When must it be finished?'}</p><div class="chips">${[['Today',0],['Tomorrow',1],['Next week',7]].map(([t,n])=>`<button data-preset="${n}">${t}</button>`).join('')}</div><div class="calendar-head"><button id="prev-month" aria-label="Previous month">‹</button><strong id="month-title"></strong><button id="next-month" aria-label="Next month">›</button></div><div id="calendar" class="calendar"></div><p id="selected-date"></p><div class="actions"><button id="no-date">Clear date</button><button class="primary" id="set-date">Set date</button></div>`,undefined,cancel);function draw(){ $('#month-title').textContent=view.toLocaleDateString('en-US',{month:'long',year:'numeric'});const first=view.getDay(),count=new Date(view.getFullYear(),view.getMonth()+1,0).getDate();$('#calendar').innerHTML=['S','M','T','W','T','F','S'].map(d=>`<span class="day-name">${d}</span>`).join('')+'<span></span>'.repeat(first)+Array.from({length:count},(_,n)=>{const date=localDate(new Date(view.getFullYear(),view.getMonth(),n+1));return `<button data-date="${date}" class="${selected===date?'selected':''}" aria-label="${dateLabel(date)}" aria-pressed="${selected===date}">${n+1}</button>`}).join('');$('#selected-date').textContent=selected?dateLabel(selected):'No date selected';document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selected=b.dataset.date;draw()})}draw();$('#prev-month').onclick=()=>{view.setMonth(view.getMonth()-1);draw()};$('#next-month').onclick=()=>{view.setMonth(view.getMonth()+1);draw()};document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const date=new Date();date.setDate(date.getDate()+Number(b.dataset.preset));selected=localDate(date);view=new Date(date.getFullYear(),date.getMonth(),1);draw()});$('#no-date').onclick=()=>{modal.close();choose('')};$('#set-date').onclick=()=>{modal.close();choose(selected)}}
function renderItem(id){const i=state.items.find(i=>i.id===id);if(!i){go('library');return}const linked=[...state.items,...state.homes].filter(x=>x.id!==id&&(i.links?.includes(x.id)||x.links?.includes(id)));app.innerHTML=`<button class="back" id="item-back">‹ Library</button>`+heading(esc(i.title),i.kind==='task'?'Task':'Note')+`<label for="item-title">Title</label><input id="item-title" value="${esc(i.title)}">${i.kind==='note'?`<label for="item-body">Content</label><textarea id="item-body">${esc(i.body)}</textarea>`:`<button class="home section" id="item-schedule">${icon('calendar')} Schedule <span>${dateLabel(i.schedule)}</span></button><button class="home" id="item-deadline">${icon('calendar')} Deadline <span>${i.deadline?dateLabel(i.deadline):'Optional'}</span></button>`}<section class="section"><h3>Primary home</h3><button class="home" id="item-home">${icon(state.homes.find(h=>h.id===i.home)?.kind||'project')}${esc(homeLabel(i.home))}<span>Change</span></button>${i.home?`<button class="quiet" id="open-home">Open home</button>`:''}</section><section class="section"><div class="row between"><h3>Connected items</h3><button class="quiet" id="item-links">Link</button></div>${linked.map(x=>state.items.includes(x)?itemRow(x):`<button class="home" data-home="${x.id}">${icon(x.kind)}${esc(x.title)}<span>›</span></button>`).join('')||'<p>No connections yet.</p>'}</section><button class="primary" id="item-save">Save changes</button>`;$('#item-back').onclick=()=>go('library');const saveText=()=>{i.title=$('#item-title').value.trim()||i.title;if(i.kind==='note')i.body=$('#item-body').value;persist()};$('#item-save').onclick=()=>{saveText();renderItem(id);toast('Changes saved')};$('#item-home').onclick=()=>{saveText();homePicker(i.home,h=>{i.home=h;persist();renderItem(id)})};if($('#open-home'))$('#open-home').onclick=()=>{saveText();go('home/'+i.home)};$('#item-links').onclick=()=>{saveText();linkPicker(i.links||[],ids=>{i.links=ids.filter(x=>x!==i.id);persist();renderItem(id)})};if(i.kind==='task'){for(const k of ['schedule','deadline'])$('#item-'+k).onclick=()=>{saveText();datePicker(k==='schedule'?'Schedule':'Deadline',i[k],v=>{i[k]=v;persist();renderItem(id)})}}bindRows();document.querySelectorAll('[data-item],[data-home]').forEach(b=>{const fn=b.onclick;b.onclick=()=>{saveText();fn()}})}
function showNewTask(){
 const task={title:'',schedule:'',home:''};
 function draw(){openModal('Add task',`<label class="sr-only" for="new-task-title">Task</label><textarea id="new-task-title" placeholder="What needs doing?">${esc(task.title)}</textarea><div class="chips"><button id="new-task-date">${icon('calendar')}${task.schedule?dateLabel(task.schedule):'Schedule'}</button><button id="new-task-home">${icon(state.homes.find(h=>h.id===task.home)?.kind||'project')}${task.home?esc(homeLabel(task.home)):'Assign'}</button></div><div class="actions"><button class="primary full" id="create-task" ${task.title.trim()?'':'disabled'}>Add task</button></div>`);
 $('#new-task-title').oninput=e=>{task.title=e.target.value;$('#create-task').disabled=!task.title.trim()};
 $('#create-task').onclick=()=>{if(!task.title.trim())return;state.items.push({id:uid(),kind:'task',title:task.title.trim(),home:task.home,schedule:task.schedule,deadline:'',links:[],completed:false});persist();modal.close();render();toast('Task added')};
 $('#new-task-date').onclick=()=>{modal.close();datePicker('Schedule',task.schedule,v=>{task.schedule=v;draw()},draw)};
 $('#new-task-home').onclick=()=>{modal.close();homePicker(task.home,v=>{task.home=v;draw()},draw)};
 }draw();
}
function showCapture(){openModal('Quick capture',`<p>Saved to Inbox. Organize when you're ready.</p><label for="capture-body">Thought</label><textarea id="capture-body" placeholder="What’s on your mind?" autofocus></textarea><button class="primary" id="save-capture">Save to Inbox</button>`);$('#save-capture').onclick=()=>{const body=$('#capture-body').value.trim();if(!body)return;state.captures.unshift({id:uid(),body,createdAt:Date.now()});persist();modal.close();go('inbox');toast('Saved to Inbox')}}
function showWidget(){openModal('Capture widget concept',`<p>The plus and label sit together in the center.</p><div class="widget-preview"><button class="widget" id="widget-capture"><b>+</b><span>Capture</span></button></div><small>Visual concept for the Android home screen widget.</small>`);$('#widget-capture').onclick=()=>{modal.close();showCapture()}}
$('#capture').onclick=showCapture;$('#reset').onclick=()=>openModal('Reset sample data?',`<p>This clears your prototype edits and restores the example thoughts.</p><button class="primary" id="confirm-reset">Reset prototype</button>`,()=>{$('#confirm-reset').onclick=()=>{state=seed();draft=null;filter='';persist();modal.close();go('inbox');render();toast('Sample data restored')}});window.addEventListener('hashchange',render);render();
